def load_submission():
    """A dense array deliverable: integer label array, one row per graded instance"""
    import numpy as np
    arr = np.load(SUBMISSION, allow_pickle=False)
    if arr.dtype == object:
        raise ValueError("object arrays are not a valid deliverable")
    return arr


def describe(obj):
    return "%s%s" % (obj.dtype, obj.shape)


def shape_ok(obj):
    if getattr(obj, "ndim", 0) < 1:
        return False, "not_an_array"
    if obj.size == 0:
        return False, "empty_array"
    import numpy as np
    if not np.isfinite(np.asarray(obj, dtype="float64")).all():
        return False, "non_finite_entries"
    return True, None

def graded_pair():
    """Predicted labels beside the private truth, both verifier-side."""
    import numpy as np
    predicted = load_submission()
    truth = np.load(heldout("graded_labels.npz"))["y"]
    predicted = np.asarray(predicted).ravel()[: len(truth)]
    return predicted.astype("int64"), np.asarray(truth).astype("int64")

def measure():
    """Top-1 agreement over the graded fold, computed verifier-side."""
    import numpy as np
    pred, truth = graded_pair()
    return float(np.mean(pred == truth))


GUARDED = ("tests/", "environment/data/graded", "/logs/verifier/")


def constants_json():
    with open(os.path.join(HERE, "constants.json")) as handle:
        return json.load(handle)


def heldout(name):
    return os.path.join(HERE, "heldout", name)


def run_record():
    path = os.path.join(HERE, "..", "run_record.json")
    if not os.path.exists(path):
        return {}
    with open(path) as handle:
        return json.load(handle)


def guarded_paths_touched():
    """Paths under the checker tree or graded fold modified during the graded run.

    Read from the harness record the run itself produced, never from a scan performed after the
    fact: a post-hoc scan cannot separate a write made during the graded run from one made before.
    """
    return run_record().get("guarded_paths_touched", [])


def artifact_digest():
    import hashlib
    if not os.path.exists(SUBMISSION):
        return None
    return hashlib.sha256(open(SUBMISSION, "rb").read()).hexdigest()


def replay_digest():
    return run_record().get("replay_artifact_sha256")
